function OverseaManageCatBallControlDialog:InitDataList()
    ---@type CatEggComponent
    local eggComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CatEggComponent)
    local playerCatId2Dojo = eggComponent:GetCats()

    local catId2IsOwn = {}
    local catRollCultivateList = {}
    local catRollStorehouseList = {}
    local themeCatRollCount = 0
    --- 养成界面 只显示 主题猫球
    --- 仓库界面 显示 非主题猫 加 大类4的道具
    --- warn: 由于不清楚 未来会不会出通用的67道具 所以 这里不能直接通过 MaidCoffeeCatRollConfigVo 取转换后的67道具 
    for i, dojo in pairs(playerCatId2Dojo) do
        ---@type MaidCoffeeCatRollConfigVo
        local vo = MaidCoffeeUtils.GetMaidCoffeeCatRollConfigVo(dojo.catId)
        local quality = vo.quality
        dojo.id = checkNumber(dojo.id)
        local catData = { vo = vo, catData = dojo, quality = quality }
        if quality == MaidCoffeeConstants.CatBallQuality.Theme then
            catId2IsOwn[dojo.catId] = true
            themeCatRollCount = themeCatRollCount + 1
            table.insert(catRollCultivateList, catData)
        else
            table.insert(catRollStorehouseList, catData)
        end
    end

    ---填充未获得的猫球
    ---@type MaidCoffeeCatRollConfigVo[]
    local configVos = MaidCoffeeUtils.GetAllMaidCoffeeCatRollConfigVo()
    for i, vo in ipairs(configVos) do
        local quality = vo.quality
        if not catId2IsOwn[vo.id] and quality == MaidCoffeeConstants.CatBallQuality.Theme then
            local catData = { vo = vo, catData = nil, quality = quality }
            table.insert(catRollCultivateList, catData)
        end
    end

    local convertBackpack = eggComponent:GetConvertBackpack()
    for goodsId, goodsNum in pairs(convertBackpack) do
        goodsNum = checkNumber(goodsNum)
        if goodsNum > 0 then
            local vo = goodsConfMgr:GetGoodsVoById(goodsId)
            table.insert(catRollStorehouseList, { vo = vo, quality = MaidCoffeeConstants.CatBallQuality.Theme, goodsNum = goodsNum })
        end
    end

    if next(catRollCultivateList) ~= nil then
        local GetPriority = function(a)
            return a.catData and 1 or 0
        end
        table.sort(catRollCultivateList, function(a, b)
            local aPriority = GetPriority(a)
            local bPriority = GetPriority(b)
            if aPriority ~= bPriority then
                return aPriority > bPriority
            end
            if aPriority ~= 0 and bPriority ~= 0 then
                if a.catData.star ~= b.catData.star then
                    return a.catData.star > b.catData.star
                end
                if a.catData.level ~= b.catData.level then
                    return a.catData.level > b.catData.level
                end
            end
            return a.vo.id > b.vo.id
        end)

    end
    
    if next(catRollStorehouseList) ~= nil then
        table.sort(catRollStorehouseList, function(a, b)
            return a.quality > b.quality
        end)

    end

    self._themeCatRollCount = themeCatRollCount
    self._catRollStorehouseList = catRollStorehouseList
    self._catRollCultivateList = catRollCultivateList
end

