function OverseaManageCatBallControlDialog:FreshUI(oldSelectType)
    if oldSelectType then
        local toggleData = self._toggleData[oldSelectType]
        KTool.SetActive(toggleData.uiNode.gameObject, false)
    end
    local toggleData = self._toggleData[self._selectType]

    ---@type OverseaManageCatBallCultivate | OverseaManageCatBallStoreHouse
    local env = self._subEnvs[self._selectType]
    if isNull(env) then
        env = CfUtils.GetLuaScr(toggleData.uiNode, toggleData.envPath)
        self._subEnvs[self._selectType] = env
    end
    KTool.SetActive(toggleData.uiNode.gameObject, true)
    if not isNull(env) then
        env:FreshUI(self, oldSelectType == nil)
    end
    self:FreshList()
end

