function OverseaManageCatBallControlDialog:LoadCatModelAsync(data, isInit)
    ---@type MaidCoffeeCatRollConfigVo
    local vo = data.vo
    ---@type CatEggDojo
    local catData = data.catData
    local playerCatId = catData and checkNumber(catData.id) or vo.id
    if self._loadCatId == playerCatId and not isInit then
        return
    end
    self:StopCoroutine()
    self:DeleteCatGameObject()
    self.co = cs_coroutine.start(function()
        ---@type CatEggComponent
        local eggComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CatEggComponent)
        local genes = catData ~= nil and catData.genes or vo.kind1
        eggComponent:LoadCatModelAsync(MaidCoffeeConstants.BornType.Adult, vo.catId, false, genes, nil, function(go)
            ---@type UnityEngine.Transform
            go.name = playerCatId
            self.catGo = go
            self._loadCatId = playerCatId
            local trans = go.transform
            trans.position = Vector3.New(-0.03, shadowVerticalOffset, 0)
            trans.localRotation = CatModelInteractionLocalRotation.Adult
        end)
    end)
end

