function OverseaManageCatBallControlDialog:FreshList()
    local count = self._selectType == ViewType.StoreHouse and #self._catRollStorehouseList or #self._catRollCultivateList
    local ScrollView = self.ScrollView
    if not ScrollView.IsListViewInit then
        ScrollView:InitGridView(count, Bind(self, self.OnGetItemByIndex))
    else
        GameUtils.ReloadData(ScrollView, count)
    end
end

function OverseaManageCatBallControlDialog:OnGetItemByIndex(listView, index)
    if index < 0 then
        return nil
    end
    local cell = listView:NewListViewItem(Cell)
    local node = GetLuaBehaviour(cell.gameObject, MaidCoffeeConstants.EnvPath.OverseaManageCatBallControlCell)
    ---@type OverseaManageCatBallControlCell
    local nodeEnv
    if not cell.IsInitHandlerCalled then
        cell.IsInitHandlerCalled = true
        node:Init()
        nodeEnv = node.Env
        nodeEnv:SetCallback(Bind(self, self.OnClickCellAction))
    else
        nodeEnv = node.Env
    end

    if nodeEnv then
        local position = index + 1
        if self._selectType == ViewType.Cultivate then
            nodeEnv:FreshCultivateUI(self._catRollCultivateList[position], position)
        elseif self._selectType == ViewType.StoreHouse then
            nodeEnv:FreshStoreHouseUI(self._catRollStorehouseList[position], position)
        end
        ---@type OverseaManageCatBallCultivate | OverseaManageCatBallStoreHouse
        local env = self._subEnvs[self._selectType]
        if not isNull(env) then
            -- print("env:GetSelectIndex()", env:GetSelectIndex())
            nodeEnv:FreshSelectState(env:GetSelectIndex() == position)

        end

    end

    return cell
end

function OverseaManageCatBallControlDialog:FreshCellSelectState(index, isSelect)
    local item = self.ScrollView:GetShownItemByItemIndex(index - 1)
    ---@type OverseaManageCatBallControlCell
    local env = CfUtils.GetLuaScr(item, MaidCoffeeConstants.EnvPath.OverseaManageCatBallControlCell)
    if not isNull(env) then
        env:FreshSelectState(isSelect)
    end
end

