function OverseaManageCatBallControlDialog:OnEventRequestSuccess(interface, data, consumes)
    if interface == Interfaces.MaidCoffeeCatLevelUp or interface == Interfaces.MaidCoffeeCatStarUp then
        ---@type CatEggComponent
        local eggComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CatEggComponent)
        local playerCatId = data.playerCatId
        for i, v in ipairs(self._catRollCultivateList) do
            ---@type CatEggDojo
            local catData = v.catData
            if catData and catData.id == playerCatId then
                local dojo = eggComponent:GetCat(playerCatId)
                dojo.id = checkNumber(dojo.id)
                self._catRollCultivateList[i].catData = dojo
                break
            end
        end

        if interface == Interfaces.MaidCoffeeCatStarUp then
            local goodsId2Count = {}
            for i, v in ipairs(consumes) do
                goodsId2Count[v.goodsId] = v.goodsNum
            end
            local catRollStorehouseList = self._catRollStorehouseList
            for i = #catRollStorehouseList, 1, -1 do
                local catData = catRollStorehouseList[i]
                local consumeCount = goodsId2Count[catData.vo.id]
                if consumeCount then
                    catData.goodsNum = catData.goodsNum - consumeCount
                    if catData.goodsNum <= 0 then
                        table.remove(catRollStorehouseList, i)
                    end
                end
            end
 
        end

        self:FreshUI()

    elseif Interfaces.MaidCoffeeCatRecycle == interface then
        self:InitDataList()
        self:FreshUI()

    end
end

